CREATE INDEX contracts_created_idx ON public.contracts USING btree (created_at DESC);
CREATE INDEX solar_permits_orphaned_idx ON public.solar_permits USING btree (orphaned) WHERE (orphaned = true);
CREATE INDEX reroof_permits_street_idx ON public.reroof_permits USING btree (street);
CREATE INDEX alert_signups_latlon_idx ON public.alert_signups USING btree (lat, lon);
CREATE UNIQUE INDEX storm_targets_dedupe_idx ON public.storm_targets USING btree (storm_date, address);
CREATE INDEX email_log_created_idx ON public.email_log USING btree (created_at DESC);
CREATE INDEX appointments_slot_start_idx ON public.appointments USING btree (slot_start);
CREATE UNIQUE INDEX appointments_closer_slot_unique ON public.appointments USING btree (closer, slot_start) WHERE ((status = 'booked'::text) AND (closer IS NOT NULL));
CREATE INDEX reroof_permits_latlon_idx ON public.reroof_permits USING btree (lat, lon);
CREATE UNIQUE INDEX team_members_email_idx ON public.team_members USING btree (lower(email));
CREATE INDEX storm_warning_hits_created_idx ON public.storm_warning_hits USING btree (created_at DESC);
CREATE UNIQUE INDEX rep_areas_unique ON public.rep_areas USING btree (area_kind, lower(area_value));
CREATE INDEX knocks_rep_idx ON public.knocks USING btree (rep, created_at DESC);
CREATE INDEX appointments_closer_idx ON public.appointments USING btree (closer, slot_start);
CREATE INDEX jobs_closer_idx ON public.jobs USING btree (closer);
CREATE UNIQUE INDEX alert_signups_phone_address_idx ON public.alert_signups USING btree (phone, upper(address));
CREATE INDEX email_failures_created_idx ON public.email_failures USING btree (created_at DESC);
CREATE INDEX solar_permits_zip_idx ON public.solar_permits USING btree (zip);
CREATE INDEX appointments_ip_created_idx ON public.appointments USING btree (ip, created_at DESC);
CREATE INDEX claim_intakes_created_at_idx ON public.claim_intakes USING btree (created_at DESC);
CREATE INDEX knocks_follow_up_due_idx ON public.knocks USING btree (rep, follow_up_at) WHERE ((follow_up_at IS NOT NULL) AND (done_at IS NULL));
CREATE UNIQUE INDEX zip_city_zip_idx ON public.zip_city USING btree (zip);
CREATE INDEX rep_areas_rep_idx ON public.rep_areas USING btree (lower(rep));
CREATE INDEX knocks_target_idx ON public.knocks USING btree (target_id, created_at DESC);
CREATE UNIQUE INDEX appointments_unassigned_slot_unique ON public.appointments USING btree (slot_start) WHERE ((status = 'booked'::text) AND (closer IS NULL));
CREATE UNIQUE INDEX contracts_sign_token_idx ON public.contracts USING btree (sign_token) WHERE (sign_token IS NOT NULL);
CREATE INDEX tarrant_roll_situs_norm_idx ON public.tarrant_roll USING btree (situs_norm);
CREATE INDEX storm_targets_storm_date_idx ON public.storm_targets USING btree (storm_date DESC, score DESC);
CREATE INDEX storm_targets_skiptrace_idx ON public.storm_targets USING btree (skip_traced_at) WHERE (skip_traced_at IS NULL);
CREATE INDEX jobs_stage_idx ON public.jobs USING btree (stage, updated_at DESC);
CREATE INDEX contracts_status_idx ON public.contracts USING btree (status, created_at DESC);
CREATE INDEX parcels_metro_lat_lon_idx ON public.parcels_metro USING btree (lat, lon);
CREATE INDEX parcels_lat_lon_idx ON public.parcels USING btree (lat, lon);
CREATE INDEX parcels_county_idx ON public.parcels USING btree (county);
CREATE INDEX login_tokens_email_idx ON public.login_tokens USING btree (email, created_at DESC);
CREATE INDEX appointments_reminder_idx ON public.appointments USING btree (slot_start) WHERE ((status = 'booked'::text) AND (reminded_at IS NULL));
CREATE INDEX jobs_setter_idx ON public.jobs USING btree (setter);
CREATE INDEX wind_reports_local_date_idx ON public.wind_reports USING btree (local_date);
CREATE INDEX cron_runs_job_ran_at_idx ON public.cron_runs USING btree (job, ran_at DESC);
CREATE INDEX job_events_job_idx ON public.job_events USING btree (job_id, created_at DESC);
CREATE INDEX leads_spam_score_idx ON public.leads USING btree (spam_score, created_at DESC);
CREATE INDEX leads_created_at_idx ON public.leads USING btree (created_at DESC);
CREATE INDEX jobs_coords_idx ON public.jobs USING btree (lat, lon) WHERE (lat IS NOT NULL);
CREATE UNIQUE INDEX storm_events_dedupe_idx ON public.storm_events USING btree (valid_at, type, lat, lon);
CREATE INDEX jobs_rep_idx ON public.jobs USING btree (lower(rep), updated_at DESC);
CREATE INDEX storm_targets_county_city_idx ON public.storm_targets USING btree (county, city);
CREATE UNIQUE INDEX jobs_target_idx ON public.jobs USING btree (storm_target_id) WHERE (storm_target_id IS NOT NULL);
CREATE INDEX storm_events_valid_at_idx ON public.storm_events USING btree (valid_at DESC);
CREATE INDEX roof_checks_created_at_idx ON public.roof_checks USING btree (created_at DESC);

CREATE OR REPLACE FUNCTION public.cell_c(lon double precision)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select (floor(lon * 100) + 9815)::int $function$
;

CREATE OR REPLACE FUNCTION public.cell_r(lat double precision)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select (3354 - floor(lat * 100))::int $function$
;

CREATE OR REPLACE FUNCTION public.norm_street(a text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select upper(regexp_replace(trim(split_part(coalesce(a, ''), ',', 1)), '\s+', ' ', 'g')) $function$
;

create view public.knock_routes as
 WITH d AS (
         SELECT upper(TRIM(BOTH FROM regexp_replace(split_part(storm_targets.address, ','::text, 1), '^[0-9]+\s*'::text, ''::text))) AS street,
            NULLIF(TRIM(BOTH FROM storm_targets.city), ''::text) AS city,
            NULLIF(NULLIF(TRIM(BOTH FROM storm_targets.zip), ''::text), '00000'::text) AS zip,
            storm_targets.hail_size_in,
            storm_targets.year_built,
            storm_targets.value AS val,
            storm_targets.storm_date,
            storm_targets.lat,
            storm_targets.lon,
            storm_targets.status,
            3959::double precision * acos(LEAST(1::double precision, cos(radians(32.78::double precision)) * cos(radians(storm_targets.lat)) * cos(radians(storm_targets.lon) - radians('-97.05'::numeric::double precision)) + sin(radians(32.78::double precision)) * sin(radians(storm_targets.lat)))) AS miles_out
           FROM storm_targets
          WHERE storm_targets.lat IS NOT NULL AND storm_targets.address IS NOT NULL
        ), g AS (
         SELECT d.street,
            d.city,
            d.zip,
            count(*) AS doors,
            count(*) FILTER (WHERE d.status = 'new'::text) AS unworked,
            max(d.hail_size_in) AS hail,
            max(d.storm_date) AS last_storm,
            avg(2026 - d.year_built) AS house_age,
            round(avg(d.year_built)) AS avg_built,
            count(d.year_built) AS age_known,
            avg(d.val) AS avg_value,
            avg(d.lat) AS lat,
            avg(d.lon) AS lon,
            min(d.miles_out) AS miles_out
           FROM d
          WHERE d.street <> ''::text AND d.city IS NOT NULL
          GROUP BY d.street, d.city, d.zip
        )
 SELECT street,
    city,
    zip,
    doors,
    unworked,
    hail,
    last_storm,
    round(house_age)::integer AS house_age,
    avg_built::integer AS avg_built,
    age_known,
    round(avg_value)::bigint AS avg_value,
    lat,
    lon,
    round(miles_out::numeric, 1) AS miles_out,
        CASE
            WHEN hail >= 1.5::double precision AND house_age >= 20::numeric THEN 'A'::text
            WHEN hail >= 1.5::double precision THEN 'B'::text
            WHEN house_age >= 20::numeric THEN 'C'::text
            ELSE 'D'::text
        END AS tier,
    round(((LEAST(doors, 40::bigint)::numeric / 40.0 * 40::numeric + LEAST(GREATEST(COALESCE(house_age, 8::numeric) - 8::numeric, 0::numeric), 20::numeric) / 20.0 * 30::numeric)::double precision + LEAST(GREATEST(hail - 1::double precision, 0::double precision), 2.5::double precision) / 2.5::double precision * 20::double precision + (GREATEST(0::numeric, 1::numeric - (CURRENT_DATE - last_storm)::numeric / 365.0) * 10::numeric)::double precision + (age_known::numeric / NULLIF(doors, 0)::numeric * 5::numeric)::double precision)::numeric, 1) AS route_score
   FROM g
  WHERE doors >= 5;

alter view public.knock_routes set (security_invoker = true);

create view public.solar_permit_zip_counts as
 SELECT zip,
    count(*)::integer AS permits
   FROM solar_permits
  WHERE zip IS NOT NULL AND zip <> ''::text
  GROUP BY zip
  ORDER BY (count(*)::integer) DESC;

alter view public.solar_permit_zip_counts set (security_invoker = true);

create view public.storm_target_cities as
 SELECT county,
    city,
    count(*)::integer AS targets
   FROM storm_targets
  WHERE city IS NOT NULL AND city <> ''::text
  GROUP BY county, city
  ORDER BY (count(*)::integer) DESC;

alter view public.storm_target_cities set (security_invoker = true);

create view public.storm_target_days as
 SELECT storm_date,
    count(*)::integer AS targets,
    count(*) FILTER (WHERE solar)::integer AS solar_targets
   FROM storm_targets
  GROUP BY storm_date
  ORDER BY storm_date DESC;

alter view public.storm_target_days set (security_invoker = true);

create view public.storm_targets_radar as
 SELECT s.id,
    s.created_at,
    s.storm_date,
    s.address,
    s.city,
    s.zip,
    s.lat,
    s.lon,
    s.owner_name,
    s.owner_mailing,
    s.phone,
    s.phone2,
    s.property_type,
    s.year_built,
    s.value,
    s.hail_size_in,
    s.wind_mph,
    s.solar,
    s.solar_source,
    s.score,
    s.status,
    s.hubspot_id,
    s.notes,
    s.absentee,
    s.county,
    s.phone_dnc,
    s.phone2_dnc,
    s.skip_traced_at,
    cs.hail12_in AS radar_in,
    cs.hail12_date AS radar_date
   FROM storm_targets s
     LEFT JOIN cell_signals cs ON cs.r = cell_r(s.lat) AND cs.c = cell_c(s.lon);

alter view public.storm_targets_radar set (security_invoker = true);

create view public.target_last_knock as
 SELECT DISTINCT ON (target_id) target_id,
    outcome,
    rep,
    created_at,
    note
   FROM knocks
  ORDER BY target_id, created_at DESC;

alter view public.target_last_knock set (security_invoker = true);

CREATE OR REPLACE FUNCTION public.doors_near(p_lat double precision, p_lon double precision, p_miles double precision DEFAULT 1.0, p_limit integer DEFAULT 200)
 RETURNS TABLE(src text, target_id uuid, county text, address text, street text, city text, zip text, owner_name text, mailing text, absentee boolean, lat double precision, lon double precision, dist_mi double precision, year_built integer, value bigint, hail_in real, hail_date date, wind_kind text, wind_date date, wind_mph real, wind_roof boolean, wind_dist_mi real, roof_year integer, roof_basis text, permit_date date, roofer text, roofer_last date, recent_roof boolean, last_outcome text, last_knock_at timestamp with time zone, score integer, reasons text[])
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with box as (
  select p_miles / 69.0 as dlat, p_miles / (69.0 * cos(radians(p_lat))) as dlon
),
tgt as (
  select distinct on (upper(trim(t.address)))
    'target'::text as src, t.id as target_id, t.county, upper(trim(t.address)) as address,
    t.city, t.zip, t.owner_name, t.owner_mailing as mailing, coalesce(t.absentee, false) as absentee,
    t.lat, t.lon, nullif(t.year_built, 0)::int as year_built, t.value::bigint as value, t.status
  from public.storm_targets t, box
  where t.lat between p_lat - box.dlat and p_lat + box.dlat
    and t.lon between p_lon - box.dlon and p_lon + box.dlon
  order by upper(trim(t.address)), t.storm_date desc
),
par as (
  select
    'parcel'::text as src, null::uuid as target_id, p.county, upper(trim(p.situs)) as address,
    p.city, left(p.zip, 5) as zip, p.owner as owner_name, upper(trim(p.mail)) as mailing,
    case
      when coalesce(trim(p.mail), '') = '' then false
      else position(
        (split_part(regexp_replace(upper(p.situs), '[^A-Z0-9 ]', '', 'g'), ' ', 1) || ' ' ||
         split_part(regexp_replace(upper(p.situs), '[^A-Z0-9 ]', '', 'g'), ' ', 2))
        in regexp_replace(upper(p.mail), '[^A-Z0-9 ]', '', 'g')) <> 1
    end as absentee,
    p.lat, p.lon, nullif(p.year_built, 0)::int as year_built, p.mkt_value::bigint as value, null::text as status
  from public.parcels p, box
  where p.lat between p_lat - box.dlat and p_lat + box.dlat
    and p.lon between p_lon - box.dlon and p_lon + box.dlon
    and (p.land_use like 'A%' or coalesce(p.land_use, '') = '')
    and coalesce(p.imp_value, 0) > 25000
    and coalesce(trim(p.situs), '') <> ''
    and coalesce(trim(p.owner), '') <> ''
),
met as (
  select
    'parcel'::text as src, null::uuid as target_id, m.county, upper(trim(m.situs)) as address,
    m.city, m.zip, m.owner as owner_name, upper(trim(m.mail)) as mailing,
    case
      when coalesce(trim(m.mail), '') = '' then false
      else position(
        (split_part(regexp_replace(upper(m.situs), '[^A-Z0-9 ]', '', 'g'), ' ', 1) || ' ' ||
         split_part(regexp_replace(upper(m.situs), '[^A-Z0-9 ]', '', 'g'), ' ', 2))
        in regexp_replace(upper(m.mail), '[^A-Z0-9 ]', '', 'g')) <> 1
    end as absentee,
    m.lat, m.lon, m.year_built, m.mkt_value as value, null::text as status
  from public.parcels_metro m, box
  where m.lat between p_lat - box.dlat and p_lat + box.dlat
    and m.lon between p_lon - box.dlon and p_lon + box.dlon
),
prm as (
  select distinct on (rp.street)
    'permit'::text as src, null::uuid as target_id, 'dallas'::text as county,
    rp.street || ', DALLAS, TX' as address, 'Dallas'::text as city, rp.zip,
    null::text as owner_name, null::text as mailing, null::boolean as absentee,
    rp.lat, rp.lon, null::int as year_built, null::bigint as value, null::text as status
  from public.reroof_permits rp, box
  where rp.lat between p_lat - box.dlat and p_lat + box.dlat
    and rp.lon between p_lon - box.dlon and p_lon + box.dlon
  order by rp.street, rp.issued_date desc
),
tgt_n as (select public.norm_street(address) as n from tgt),
met_n as (select public.norm_street(address) as n from met),
houses as (
  select * from tgt
  union all
  select * from par where not exists (select 1 from tgt where tgt.address = par.address)
  union all
  select * from met where not exists (select 1 from tgt_n where tgt_n.n = public.norm_street(met.address))
  union all
  select * from prm
  where not exists (select 1 from tgt_n where tgt_n.n = public.norm_street(prm.address))
    and not exists (select 1 from met_n where met_n.n = public.norm_street(prm.address))
),
scored as (
  select
    h.*,
    3958.8 * 2 * asin(sqrt(
      power(sin(radians(h.lat - p_lat) / 2), 2) +
      cos(radians(p_lat)) * cos(radians(h.lat)) * power(sin(radians(h.lon - p_lon) / 2), 2)
    )) as dist_mi,
    s.hail12_in, s.hail12_date, s.hail24_in, s.hail24_date, s.big_hail_old_date,
    s.wind_kind, s.wind_date, s.wind_mph, s.wind_roof, s.wind_dist_mi,
    k.outcome as last_outcome, k.created_at as last_knock_at,
    pm.issued_date as permit_date, pm.contractor as roofer, pm.contractor_last as roofer_last,
    extract(year from pm.issued_date)::int as permit_year,
    case when s.big_hail_old_date is not null
      then extract(year from s.big_hail_old_date)::int + 1 end as hail_roof_year
  from houses h
  left join public.cell_signals s on s.r = public.cell_r(h.lat) and s.c = public.cell_c(h.lon)
  left join public.target_last_knock k on k.target_id = h.target_id
  left join lateral (
    select rp.issued_date, nullif(rp.contractor, '') as contractor, rp.contractor_last
    from public.reroof_permits rp
    where h.county ilike 'dallas%'
      and rp.street = public.norm_street(h.address)
      and (rp.zip is null or h.zip is null or left(h.zip, 5) = rp.zip)
    order by rp.issued_date desc
    limit 1
  ) pm on true
),
basis as (
  select sc.*,
    greatest(sc.year_built, sc.hail_roof_year, sc.permit_year) as roof_year,
    case
      when sc.permit_year is not null
        and sc.permit_year >= coalesce(sc.hail_roof_year, 0)
        and sc.permit_year >= coalesce(sc.year_built, 0) then 'permit'
      when sc.hail_roof_year is not null and sc.hail_roof_year >= coalesce(sc.year_built, 0) then 'hail'
      when sc.year_built is not null then 'built'
    end as roof_basis
  from scored sc
),
pts as (
  select b.*,
    extract(year from current_date)::int - b.year_built as home_age,
    (b.roofer is not null and b.roofer_last <= date '2025-03-15') as roofer_quiet,
    (
      (b.roof_basis = 'permit' and b.permit_date >= date '2021-01-01') or
      (b.roof_basis = 'hail' and b.big_hail_old_date >= date '2023-01-01')
    ) as recent_roof,
    (case
       when b.hail12_in >= 2.5 then 40 when b.hail12_in >= 1.75 then 32
       when b.hail12_in >= 1.25 then 22 when b.hail12_in >= 1 then 15
       when b.hail12_in >= 0.75 then 6 else 0 end)
    + (case when b.hail24_in >= 1.75 then 6 when b.hail24_in >= 1 then 3 else 0 end)
    + (case
         when b.wind_date >= current_date - 365 then
           (case when b.wind_kind = 'tornado' then 25 else 12 end)
           + (case when b.wind_roof then 8 else 0 end)
           + (case when b.wind_mph >= 70 then 4 else 0 end)
         when b.wind_date is not null then 4 else 0 end)
    + (case
         when b.roof_basis = 'built' and extract(year from current_date)::int - b.year_built between 15 and 30 then 18
         when b.roof_basis = 'built' and extract(year from current_date)::int - b.year_built > 30 then 5
         when b.roof_basis = 'permit' and b.roofer is not null and b.roofer_last <= date '2025-03-15' then 18
         when b.roof_basis = 'permit' and b.roofer is not null then 8
         when b.roof_basis = 'permit' then 6
         when b.roof_basis = 'hail' and b.big_hail_old_date >= date '2023-01-01' then 10
         else 0 end)
    + (case when b.absentee is null then 0 when b.absentee then -12 else 6 end)
    + (case when b.value >= 500000 then 4 when b.value >= 300000 then 2 else 0 end)
    as score
  from basis b
  where b.dist_mi <= p_miles
    and coalesce(b.status, '') <> 'converted'
)
select
  src, target_id, county, address,
  regexp_replace(trim(split_part(address, ',', 1)), '\s+', ' ', 'g') as street,
  coalesce(nullif(trim(city), ''), initcap(county) || ' County') as city,
  zip, owner_name, mailing, absentee, lat, lon,
  round(dist_mi::numeric, 2)::double precision, year_built, value,
  hail12_in, hail12_date, wind_kind, wind_date, wind_mph, wind_roof, wind_dist_mi,
  roof_year, roof_basis, permit_date, roofer, roofer_last, recent_roof,
  last_outcome, last_knock_at, score::int,
  array_remove(array[
    case when hail12_in >= 0.75 then
      'About ' || to_char(hail12_in, 'FM90.0') || ' in hail on radar, ' || to_char(hail12_date, 'Mon FMDD') end,
    case when wind_date >= current_date - 365 then
      case
        when wind_kind = 'tornado' then 'Tornado reported '
        when wind_roof then 'Roof damage reported '
        when wind_kind = 'wind_damage' then 'Wind damage reported '
        else to_char(wind_mph, 'FM999') || ' mph gust reported '
      end || to_char(wind_dist_mi, 'FM0.0') || ' mi away, ' || to_char(wind_date, 'Mon FMDD') end,
    case
      when roof_basis = 'permit' and roofer_quiet then
        'Re-roofed ' || to_char(permit_date, 'Mon YYYY') || ' by ' ||
        regexp_replace(initcap(roofer), '\mLlc\M', 'LLC', 'g') ||
        '. Their last Dallas permit on record: ' || to_char(roofer_last, 'Mon YYYY')
      when roof_basis = 'permit' and roofer is not null then
        'Re-roofed ' || to_char(permit_date, 'Mon YYYY') || ' by ' ||
        regexp_replace(initcap(roofer), '\mLlc\M', 'LLC', 'g')
      when roof_basis = 'permit' then
        'Re-roofed ' || to_char(permit_date, 'Mon YYYY') || ' (city permit)'
      when roof_basis = 'hail' and big_hail_old_date >= date '2023-01-01' then
        'Golf-ball+ hail on radar ' || to_char(big_hail_old_date, 'Mon YYYY') || ': roof likely replaced since. Ask who did it'
      when roof_basis = 'hail' then
        'Golf-ball+ hail on radar ' || to_char(big_hail_old_date, 'Mon YYYY') || ': roof likely replaced since'
      when roof_basis = 'built' and home_age between 15 and 30 then
        'Built ' || year_built || ', no big hail here since 2020: roof may be original'
      when roof_basis = 'built' and home_age > 30 then
        'Built ' || year_built || ', no big hail here since 2020' end,
    case when absentee is null then null when absentee then 'Owner lives elsewhere' else 'Owner lives here' end
  ], null) as reasons
from pts
order by score desc, dist_mi asc
limit p_limit;
$function$
;

CREATE OR REPLACE FUNCTION public.field_doors(p_lat double precision, p_lon double precision, p_miles double precision DEFAULT 1, p_min_hail real DEFAULT 2, p_zip text DEFAULT NULL::text, p_order text DEFAULT 'dist'::text, p_limit integer DEFAULT 1000, p_view text DEFAULT 'hail'::text)
 RETURNS TABLE(src text, target_id uuid, county text, address text, city text, zip text, owner_name text, absentee boolean, lat double precision, lon double precision, dist_mi double precision, year_built integer, value bigint, hail_in real, hail_date date, storm_date date, wind_kind text, wind_date date, wind_roof boolean, wind_dist_mi real, roof_year integer, roof_basis text, permit_date date, roofer text, recent_roof boolean, reasons text[], score integer, wind_mph real, big_hail_old_date date, storm_days date[], roof_original boolean, no_permit_since date, priority boolean, phone text, phone_dnc boolean, last_outcome text, last_knock_at timestamp with time zone, last_rep text, last_note text, follow_up_at timestamp with time zone, job_id uuid, job_stage text, appt_at timestamp with time zone, appt_status text, total bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with m as (
  select least(greatest(coalesce(p_miles, 1), 0.1), 3) as mi,
         extract(year from current_date)::int as yr
),
worked_jobs as (
  select distinct j.storm_target_id from public.jobs j where j.storm_target_id is not null
),
job_keys as (
  select distinct public.norm_street(split_part(j.address, ',', 1)) as nkey
  from public.jobs j where j.address is not null
),
base as (
  select d.* from m, public.doors_near(p_lat, p_lon, m.mi, 20000) d
  where (p_zip is null or left(d.zip, 5) = p_zip)
),
cells as (
  select distinct public.cell_r(b.lat) as r, public.cell_c(b.lon) as c from base b
),
cell_storms as (
  select cl.r, cl.c, array_agg(distinct h.local_date) as days
  from cells cl
  join public.hail_days h
    on h.r between cl.r - 1 and cl.r + 1 and h.c between cl.c - 1 and cl.c + 1
   and h.mesh_in >= 1.25 and h.local_date >= current_date - 730
  group by cl.r, cl.c
),
sig as (
  select b.*, s.big_hail_old_date, coalesce(cs.days, '{}'::date[]) as days,
    upper(trim(b.city)) = 'DALLAS' as dallas_city,
    case when upper(trim(b.city)) = 'DALLAS' then b.permit_date
         else greatest(b.permit_date, s.big_hail_old_date) end as roof_since,
    b.year_built between m.yr - 30 and m.yr - 15
      and case when upper(trim(b.city)) = 'DALLAS' then b.permit_date is null
               else b.roof_basis = 'built' end as roof_original,
    (b.wind_kind in ('tornado', 'wind_damage') or coalesce(b.wind_roof, false)
      or coalesce(b.wind_mph, 0) >= 70) as wind_dmg
  from base b
  cross join m
  left join public.cell_signals s on s.r = public.cell_r(b.lat) and s.c = public.cell_c(b.lon)
  left join cell_storms cs on cs.r = public.cell_r(b.lat) and cs.c = public.cell_c(b.lon)
),
sig1 as (
  select g.*,
    (coalesce(g.hail_in, 0) >= 1.25 or (g.wind_dmg and g.wind_date >= current_date - 365)) as storm12
  from sig g
),
sig2 as (
  select g.*,
    array(
      select distinct case when g.hail_date is not null and abs(x.d - g.hail_date) <= 1
                           then g.hail_date else x.d end
      from unnest(g.days) as x(d)
      where g.roof_since is null or x.d > g.roof_since
      union
      select g.wind_date
      where g.wind_dmg and g.wind_date >= current_date - 730
        and (g.roof_since is null or g.wind_date > g.roof_since)
        and not exists (select 1 from unnest(g.days) as y(d) where abs(y.d - g.wind_date) <= 1)
      order by 1
    ) as storm_days,
    case when g.dallas_city then
      case when coalesce(g.hail_in, 0) >= 1.25 and (g.permit_date is null or g.permit_date < g.hail_date)
             then g.hail_date
           when g.big_hail_old_date is not null
            and (g.permit_date is null or g.permit_date < g.big_hail_old_date)
             then g.big_hail_old_date
      end
    end as no_permit_since
  from sig1 g
),
near as (
  select n.*, (n.storm12 and (n.roof_original or cardinality(n.storm_days) >= 2)) as priority
  from sig2 n, m
  where
    n.last_outcome is not null
    or (n.target_id is not null
        and exists (select 1 from worked_jobs w where w.storm_target_id = n.target_id))
    or public.norm_street(split_part(n.address, ',', 1)) in (select nkey from job_keys)
    or case coalesce(p_view, 'hail')
         when 'older' then n.roof_original
         when 'priority' then n.storm12 and (n.roof_original or cardinality(n.storm_days) >= 2)
         else (p_min_hail is null or n.hail_in >= p_min_hail)
       end
),
conv as (
  select t.id as target_id, t.county, upper(trim(t.address)) as address, t.city, t.zip,
    t.owner_name, coalesce(t.absentee, false) as absentee, t.lat, t.lon,
    3958.8 * 2 * asin(sqrt(
      power(sin(radians(t.lat - p_lat) / 2), 2) +
      cos(radians(p_lat)) * cos(radians(t.lat)) * power(sin(radians(t.lon - p_lon) / 2), 2)
    )) as dist_mi,
    nullif(t.year_built, 0)::int as year_built, t.value::bigint as value,
    t.radar_in as hail_in, t.radar_date as hail_date
  from public.storm_targets_radar t, m
  where t.status = 'converted'
    and t.lat between p_lat - m.mi / 69.0 and p_lat + m.mi / 69.0
    and t.lon between p_lon - m.mi / (69.0 * cos(radians(p_lat)))
                  and p_lon + m.mi / (69.0 * cos(radians(p_lat)))
    and (p_zip is null or left(t.zip, 5) = p_zip)
),
alld as (
  select n.src, n.target_id, n.county, n.address, n.city, n.zip, n.owner_name, n.absentee,
    n.lat, n.lon, n.dist_mi, n.year_built, n.value, n.hail_in, n.hail_date,
    n.wind_kind, n.wind_date, n.wind_roof, n.wind_dist_mi,
    n.roof_year, n.roof_basis, n.permit_date, n.roofer, n.recent_roof, n.reasons, n.score,
    n.wind_mph, n.big_hail_old_date, n.storm_days, n.roof_original, n.no_permit_since, n.priority
  from near n
  union all
  select 'target', c.target_id, c.county, c.address, c.city, c.zip, c.owner_name, c.absentee,
    c.lat, c.lon, c.dist_mi, c.year_built, c.value, c.hail_in, c.hail_date,
    null, null, null, null, null, null, null, null, null, null, null,
    null, null, null, null, null, false
  from conv c, m
  where c.dist_mi <= m.mi
),
picked as (
  select a.*, count(*) over () as total
  from alld a
  order by
    case when p_order = 'hail' then -coalesce(a.hail_in, 0) else 0 end,
    case when p_order = 'score' and a.priority then 0 when p_order = 'score' then 1 else 0 end,
    case when p_order = 'score' then -coalesce(a.score, 0) else 0 end,
    a.dist_mi
  limit least(greatest(coalesce(p_limit, 1000), 1), 1000)
),
jb as (
  select j.id, j.stage, j.appointment_id, j.storm_target_id, j.updated_at,
    public.norm_street(split_part(j.address, ',', 1)) as nkey
  from public.jobs j
),
jb_addr as (
  select distinct on (nkey) id, stage, appointment_id, nkey from jb
  where nkey is not null order by nkey, updated_at desc
)
select p.src, p.target_id, p.county, p.address, p.city, p.zip, p.owner_name, p.absentee,
  p.lat, p.lon, p.dist_mi, p.year_built, p.value, p.hail_in, p.hail_date, t.storm_date,
  p.wind_kind, p.wind_date, p.wind_roof, p.wind_dist_mi,
  p.roof_year, p.roof_basis, p.permit_date, p.roofer, p.recent_roof, p.reasons, p.score,
  p.wind_mph, p.big_hail_old_date, p.storm_days, p.roof_original, p.no_permit_since, p.priority,
  case when coalesce(t.phone_dnc, false) then null else t.phone end as phone, t.phone_dnc,
  k.outcome, k.created_at, k.rep, k.note,
  cb.follow_up_at,
  coalesce(j1.id, j2.id), coalesce(j1.stage, j2.stage), ap.slot_start, ap.status,
  p.total
from picked p
left join public.storm_targets t on t.id = p.target_id
left join public.target_last_knock k on k.target_id = p.target_id
left join lateral (
  select kn.follow_up_at from public.knocks kn
  where kn.target_id = p.target_id and kn.outcome = 'come_back'
    and kn.done_at is null and kn.follow_up_at is not null
  order by kn.created_at desc limit 1
) cb on true
left join jb j1 on j1.storm_target_id = p.target_id
left join jb_addr j2 on j1.id is null and j2.nkey = public.norm_street(split_part(p.address, ',', 1))
left join public.appointments ap on ap.id = coalesce(j1.appointment_id, j2.appointment_id);
$function$;
-- Rep onboarding sequence: when it started for each person, and every email it sent.
alter table public.team_members add column if not exists onboarding_started_at timestamptz;

create table if not exists public.onboarding_sends (
  id bigserial primary key,
  member_id bigint not null references public.team_members(id) on delete cascade,
  -- welcome | reminder | gate | permit | ready | office_turn | office_stalled
  kind text not null,
  -- One row per key per person, so an overlapping run can never send twice.
  key text not null,
  to_addr text,
  ok boolean,
  detail jsonb,
  sent_at timestamptz not null default now(),
  unique (member_id, key)
);
create index if not exists onboarding_sends_member_idx on public.onboarding_sends (member_id, sent_at);
alter table public.onboarding_sends enable row level security;
-- Regions: a regional leader over several closer-led teams.
create table if not exists public.regions (
  id bigint generated always as identity primary key,
  name text not null,
  leader_member_id bigint references public.team_members(id) on delete set null,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.regions enable row level security;
alter table public.teams add column if not exists region_id bigint references public.regions(id) on delete set null;
-- Which page and ad brought a booking (utm_*, page, referrer).
alter table public.appointments add column if not exists attribution jsonb;
